const cfg = $('Config').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && (r.Topic || r.topic));
// Several rows share one topic (one row per frame) → dedupe
const existing = [...new Set(rows.map(r => String(r.Topic || r.topic).trim()).filter(Boolean))];
// Only send the most recent 150 topics to keep the prompt small
const recent = existing.slice(-150);
return [{
  json: {
    ...cfg,
    existing_topics: existing,
    existing_count: existing.length,
    existing_topic_block: recent.length ? recent.join('  ||  ') : 'NONE - first run'
  }
}];

function extractText(resp) {
  if (!resp) return null;
  if (typeof resp === 'string') return resp;
  function fromOutput(obj) {
    if (!obj || !Array.isArray(obj.output)) return null;
    for (const item of obj.output) {
      if (item && item.type === 'message' && Array.isArray(item.content)) {
        for (const c of item.content) {
          if (c && typeof c.text === 'string' && c.text.trim()) return c.text;
        }
      }
    }
    return null;
  }
  let t = fromOutput(resp);
  if (t) return t;
  if (resp.data) { t = fromOutput(resp.data); if (t) return t; }
  if (resp.choices && resp.choices[0] && resp.choices[0].message) return resp.choices[0].message.content;
  if (resp.data && resp.data.choices && resp.data.choices[0] && resp.data.choices[0].message) return resp.data.choices[0].message.content;
  if (typeof resp.text === 'string') return resp.text;
  if (typeof resp.content === 'string') return resp.content;
  return null;
}
function extractJson(str) {
  if (!str) return null;
  try { return JSON.parse(str); } catch (e) {}
  const cleaned = String(str).replace(/```json/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(cleaned); } catch (e) {}
  const a = cleaned.indexOf('{'), b = cleaned.lastIndexOf('}');
  if (a !== -1 && b !== -1) { try { return JSON.parse(cleaned.slice(a, b + 1)); } catch (e) {} }
  return null;
}

const text = extractText($input.first().json);
if (!text) throw new Error('No text in KIE response. Raw: ' + JSON.stringify($input.first().json).slice(0, 500));

const parsed = extractJson(text);
const list = parsed && (Array.isArray(parsed.stories) ? parsed.stories : (Array.isArray(parsed.topics) ? parsed.topics : null));
if (!list) throw new Error('Could not parse stories[]. Preview: ' + text.slice(0, 500));

const existing = ($('Merge Config + Existing').first().json.existing_topics || []).map(t => String(t).toLowerCase());
const STOP = new Set(['the','a','an','and','or','for','to','of','in','on','with','your','you','best','top','how','why','is','are','it','this','that','travel','wellness','guide','tips','story','stories','vs','quick']);
const words = s => String(s).toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w && !STOP.has(w));

const out = [];
const seenThisRun = [];
for (const t of list) {
  if (!t || !t.topic) continue;
  const w = new Set(words(t.topic));
  let dupOf = null, best = 0;
  for (const ex of existing.concat(seenThisRun)) {
    const ew = words(ex);
    if (!ew.length || !w.size) continue;
    const overlap = ew.filter(x => w.has(x)).length;
    const ratio = overlap / Math.min(ew.length, w.size);
    if (ratio > best) { best = ratio; dupOf = ex; }
  }
  seenThisRun.push(String(t.topic).toLowerCase());
  const secondary = Array.isArray(t.secondary_keywords) ? t.secondary_keywords : [];
  out.push({ json: {
    topic: t.topic,
    story_format: t.story_format || 'Quick tips',
    primary_keyword: t.primary_keyword || '',
    secondary_keywords: secondary,
    goal: t.goal || 'Engagement',
    why_now: t.why_now || '',
    data_note: t.data_note || 'AI estimate - no live data used',
    keywords: [t.primary_keyword, ...secondary].filter(Boolean).join(', '),
    is_duplicate: best >= 0.6,
    duplicate_of: dupOf,
    duplicate_similarity: Math.round(best * 100)
  }});
}
if (!out.length) throw new Error('No usable story ideas in the research output.');
return out;

