const text = extractText($json);
if (!text) throw new Error('No text in KIE response. Keys: ' + Object.keys($json).join(', '));
const parsed = extractJson(text);
if (!parsed || typeof parsed.story_score === 'undefined') throw new Error('Bad score JSON: ' + text.slice(0, 400));

const src = $('Parse Story Ideas + Duplicate Check').item.json;
const cfg = $('Config').first().json;

let score = Math.max(0, Math.min(100, Math.round(Number(parsed.story_score) || 0)));
let opp = String(parsed.opportunity || '').toUpperCase().trim();
if (['HIGH', 'MEDIUM', 'LOW'].indexOf(opp) === -1) opp = score >= 75 ? 'HIGH' : score >= 60 ? 'MEDIUM' : 'LOW';
if (src.is_duplicate) opp = 'LOW';

const threshold = Number(cfg.min_story_score) || 60;
const meets = opp !== 'LOW' && score >= threshold && !src.is_duplicate;

let note;
if (src.is_duplicate) note = 'Auto-rejected: ' + src.duplicate_similarity + '% similar to existing story "' + src.duplicate_of + '"';
else if (!meets) note = 'Auto-rejected: story score ' + score + '/100 is below ' + threshold;
else note = 'Auto-approved for story generation (' + opp + ', ' + score + '/100)';

return { json: {
  ...src,
  story_score: score,
  opportunity: opp,
  score_breakdown: parsed.score_breakdown || {},
  best_platform: parsed.best_platform || 'Both',
  best_sticker: parsed.best_sticker || 'poll',
  target_audience: parsed.target_audience || '',
  why_it_works: parsed.why_it_works || '',
  main_risk: parsed.main_risk || '',
  meets_threshold: meets,
  decision_note: note
}};

