if (!text) throw new Error('No text in KIE response. Keys: ' + Object.keys($json).join(', '));
const parsed = extractJson(text);
if (!parsed || !Array.isArray(parsed.frames) || !parsed.frames.length) throw new Error('Bad story JSON: ' + text.slice(0, 400));

const src = $('Parse Score + Decision').item.json;
const d = new Date();
const stamp = d.toISOString().slice(0, 10).replace(/-/g, '');
const rand = Math.random().toString(36).slice(2, 6).toUpperCase();

const tags = Array.isArray(parsed.hashtags)
  ? parsed.hashtags.map(h => String(h).trim()).filter(Boolean).map(s => s.startsWith('#') ? s : '#' + s.replace(/\s+/g, ''))
  : [];

return { json: {
  story_id: 'ST-' + stamp + '-' + rand,
  date: d.toISOString().slice(0, 10),
  topic: src.topic,
  story_format: src.story_format,
  keywords: src.keywords,
  goal: src.goal,
  story_score: src.story_score,
  opportunity: src.opportunity,
  best_platform: src.best_platform,
  decision_note: src.decision_note,
  story_angle: parsed.story_angle || '',
  music_mood: parsed.music_mood || '',
  caption: parsed.caption || '',
  hashtags: tags.join(' '),
  frames: parsed.frames
}};

const cfg = $('Config').first().json;
const renderText = cfg.render_text_on_image === true || String(cfg.render_text_on_image).toLowerCase() === 'true';
const STYLE = ', photorealistic, vertical 9:16 composition for Instagram and Facebook Stories, shot on 35mm, natural golden-hour light, soft depth of field, premium editorial travel photography, muted earthy and sage colour palette, no watermark, no logo, no people looking directly at camera, ultra detailed';

// Publish time: tomorrow at posting_hour_utc, frames spaced a few minutes apart (keeps order in Postiz)
const base = new Date();
base.setUTCDate(base.getUTCDate() + 1);
base.setUTCHours(Number(cfg.posting_hour_utc) || 17, 0, 0, 0);
const gap = Number(cfg.minutes_between_frames) || 2;

const out = [];
const items = $input.all();
items.forEach((item, idx) => {
  const s = item.json;
  const frames = s.frames || [];
  // Stagger each story set by 1 hour so stories don't overlap
  const storyBase = new Date(base.getTime() + idx * 60 * 60 * 1000);
  frames.forEach((f, i) => {
    const num = i + 1;
    const onScreen = String(f.on_screen_text || '').replace(/"/g, "'").replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
    let prompt = String(f.image_prompt || '').replace(/\s+/g, ' ').trim();
    if (prompt.length < 20) prompt = 'A serene vertical wellness travel scene about ' + s.topic;
    prompt = prompt.replace(/[.\s]+$/, '') + STYLE;
    if (renderText && onScreen) {
      prompt += '. In the calm upper third, overlay large, bold, clean modern sans-serif white text with a subtle soft shadow, perfectly spelled, reading exactly: "' + onScreen + '". No other text anywhere in the image.';
    } else {
      prompt += '. Keep the upper third as clean empty negative space for a text overlay. No text in the image.';
    }
    const sticker = String(f.sticker_type || 'none').toLowerCase();
    const scheduled = new Date(storyBase.getTime() + i * gap * 60 * 1000).toISOString();
    let notes = s.decision_note || '';
    if (sticker !== 'none') notes = ('Add ' + sticker.toUpperCase() + ' sticker manually in-app if needed: ' + (f.sticker_content || (sticker === 'link' ? (cfg.link_url || '') : '')) + '. ' + notes).trim();

    out.push({
      json: {
        story_id: s.story_id,
        frame_id: s.story_id + '-F' + num,
        frame_number: num,
        total_frames: frames.length,
        date: s.date,
        topic: s.topic,
        story_format: s.story_format,
        keywords: s.keywords,
        story_score: s.story_score,
        opportunity: s.opportunity,
        best_platform: s.best_platform,
        story_angle: s.story_angle,
        frame_role: f.role || (num === 1 ? 'Hook' : num === frames.length ? 'CTA' : 'Value'),
        on_screen_text: onScreen,
        sticker_type: sticker,
        sticker_content: f.sticker_content || '',
        link_url: (sticker === 'link' || num === frames.length) ? (cfg.link_url || '') : '',
        alt_text: f.alt_text || '',
        music_mood: s.music_mood,
        caption: s.caption,
        hashtags: s.hashtags,
        image_prompt: prompt,
        platforms: cfg.platforms,
        postiz_post_type: cfg.postiz_post_type || 'story',
        scheduled_at: scheduled,
        human_notes: notes
      },
      pairedItem: { item: idx }
    });
  });
});
return out;

const res = $json || {};
const src = $('Split Frames + Build 9:16 Prompts').item.json;
const createRes = $('KIE.AI — Create 9:16 Image Task').item.json || {};
const taskId = (createRes.data && createRes.data.taskId) ? createRes.data.taskId : '';
const state = (res.data && res.data.state) ? res.data.state : ((res.data && res.data.successFlag) ? 'success' : 'unknown');

let url = '';
if (res.data && res.data.resultJson) {
  try {
    const r = typeof res.data.resultJson === 'string' ? JSON.parse(res.data.resultJson) : res.data.resultJson;
    if (r && Array.isArray(r.resultUrls) && r.resultUrls.length) url = r.resultUrls[0];
    else if (r && r.resultUrl) url = r.resultUrl;
    else if (r && Array.isArray(r.urls) && r.urls.length) url = r.urls[0];
  } catch (e) {}
}
if (!url && res.data && res.data.response && Array.isArray(res.data.response.resultUrls)) url = res.data.response.resultUrls[0] || '';
if (!url && res.data && Array.isArray(res.data.resultUrls)) url = res.data.resultUrls[0] || '';
if (!url && res.data && typeof res.data.imageUrl === 'string') url = res.data.imageUrl;

let note = src.human_notes || '';
note = url
  ? ('Image generated. ' + note).trim()
  : ('KIE image not ready (state: ' + state + ', task: ' + taskId + '). Increase Wait or re-fetch. ' + note).trim();

return { json: { ...src, kie_image_url: url, kie_task_id: taskId, kie_state: state, human_notes: note } };
